import {deliveryResults} from './delivery.js';
import {dateNum,dateStr} from './model.js';
import {criticalMilestones} from './build-milestones.js';
import {buildTimeline,stepTimeSettings} from './milestone-view.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1}),d=x=>x?new Date(x+'T12:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'—';
const badge=(tone,text)=>`<span class="badge ${tone}"><span class="status-dot"></span>${esc(text)}</span>`;
function progressChart(o,rows,selected){
 const W=520,H=126,L=38,R=15,T=12,B=29,first=dateNum(rows[0].date),last=dateNum(rows.at(-1).date),X=n=>L+(n-first)/Math.max(1,last-first)*(W-L-R),Y=n=>T+(H-T-B)*(1-n/o.total);
 const points=rows.map(r=>({date:r.date,n:r.criticalProgress.find(x=>x.id===o.id)?.ready||0}));
 return `<svg viewBox="0 0 ${W} ${H}" class="critical-chart" role="img" aria-label="${esc(o.part)} ${o.week} planned Akro-ready sheets over time"><line x1="${L}" x2="${W-R}" y1="${Y(o.total)}" y2="${Y(o.total)}" stroke="#ccdcd5" stroke-dasharray="3 4"/><line x1="${L}" x2="${W-R}" y1="${Y(0)}" y2="${Y(0)}" stroke="#e3ebef"/><text x="${L-7}" y="${Y(o.total)+4}" text-anchor="end">${o.total}</text><text x="${L-7}" y="${Y(0)+4}" text-anchor="end">0</text><polyline points="${points.map(p=>`${X(dateNum(p.date))},${Y(p.n)}`).join(' ')}" fill="none" stroke="#168773" stroke-width="2.5" stroke-linejoin="round"/><line x1="${X(dateNum(selected))}" x2="${X(dateNum(selected))}" y1="${T}" y2="${H-B}" stroke="#849aaa" stroke-dasharray="3 3"/>${o.needBy>=first&&o.needBy<=last?`<line x1="${X(o.needBy)}" x2="${X(o.needBy)}" y1="${T}" y2="${H-B}" stroke="#d4a54d" stroke-dasharray="3 3"><title>Akro needed ${d(dateStr(o.needBy))}</title></line>`:''}${[0,Math.floor((rows.length-1)/2),rows.length-1].map(i=>`<text x="${X(dateNum(rows[i].date))}" y="${H-9}" text-anchor="middle">${d(rows[i].date)}</text>`).join('')}<title>Green: released plus reserved sheets. Gray: selected date. Gold: Akro-needed date.</title></svg>`;
}
export function criticalBuildsView(s,rows,date,groupId){
 const groups=deliveryResults(rows).filter(o=>o.priority==='critical'),row=rows.find(r=>r.date===date),progress=new Map(row.criticalProgress.map(x=>[x.id,x])),zero=o=>({filled:0,reserved:0,inOven:0,lateOven:0,uncovered:o.total,ready:0,percent:0}),at=o=>progress.get(o.id)||zero(o);
 const totals=groups.reduce((n,o)=>{const x=at(o);n.required+=o.total;n.ready+=x.ready;n.inOven+=x.inOven;n.uncovered+=x.uncovered;return n},{required:0,ready:0,inOven:0,uncovered:0}),covered=groups.filter(o=>o.inPlan&&!o.partial&&at(o).ready===o.total).length,late=groups.filter(o=>o.tone==='red').length;
 const selected=groups.find(o=>o.id===groupId)||groups[0],milestones=criticalMilestones(s,rows);
 return `<section class="critical-top"><div><span class="eyebrow">PRIORITY BUILDS · PLANNED PROGRESS</span><h2>Critical builds, in focus.</h2><p>Follow Akro readiness for every group marked Critical. Select a date to see its planned position; quantities are forecasts, not recorded shop-floor completion or shipments.</p></div><button data-tab="delivery">Manage priorities & dates ↗</button></section>
 <section class="card critical-datebar"><div><label>View planned progress on<input type="date" id="criticalDate" aria-label="Critical build progress date" value="${date}" min="${s.settings.start}" max="${s.settings.end}"></label><span class="critical-date-context">${row.holiday?'Holiday · forming, unloading & waterjet off':row.closed?'Waterjet shutdown · oven work allowed':'Operating day'}</span></div><div class="inline"><button id="criticalPrev" aria-label="Previous progress day" ${date<=s.settings.start?'disabled':''}>←</button><button id="criticalNext" aria-label="Next progress day" ${date>=s.settings.end?'disabled':''}>→</button><button id="criticalToday">Today</button><button id="criticalEnd">Plan end</button><button id="milestoneCsv">↓ Export milestone CSV</button><button id="criticalCsv" ${groups.length?'':'disabled'}>↓ Export progress CSV</button></div></section>
 ${stepTimeSettings(s)}
 ${!groups.length?'<section class="card empty-critical"><h3>No critical builds selected</h3><p>Set a product/week group to Critical in Order readiness. It will appear here automatically.</p><button class="primary" data-tab="delivery">Choose critical builds →</button></section>':`
 <div class="critical-summary"><div class="card"><span>Critical build groups</span><strong>${groups.length}</strong><small>${covered} fully covered with cured Akro on ${d(date)}</small></div><div class="card"><span>Akro ready · selected date</span><strong>${f(totals.ready)} <i>/ ${f(totals.required)}</i></strong><small>Released downstream + reserved supermarket sheets</small></div><div class="card"><span>Assigned in oven</span><strong>${f(totals.inOven)} <i>sheets</i></strong><small>${f(totals.uncovered)} sheets still uncovered</small></div><div class="card"><span>Projected late / not covered</span><strong class="${late?'red-text':''}">${late}</strong><small>${groups.filter(o=>o.lead==null).length} groups need remaining lead time to ready to ship</small></div></div>
 <div class="critical-cards">${groups.map(o=>{
  const x=at(o),readyDate=rows.find(r=>r.criticalProgress.some(x=>x.id===o.id&&x.ready===o.total))?.date,stockDate=readyDate&&!o.partial?d(readyDate):'Not covered in plan';
  return `<article class="card critical-build"><div class="critical-build-head"><div><span class="critical-week">${o.week} · ${o.kind==='thin'?'3/4"':'1 1/8"'} AKRO</span><h3>${esc(o.part)}</h3><p>${f(o.cases)} cases · ${f(o.total)} whole sheets required</p></div><span class="critical-tag">Critical</span></div>
   <div class="critical-readiness"><span>Akro readiness · ${d(date)}</span><strong>${f(x.percent)}%</strong></div><div class="build-progress" role="progressbar" aria-label="${esc(o.part)} ${o.week} Akro readiness" aria-valuemin="0" aria-valuemax="${o.total}" aria-valuenow="${x.ready}">${[['released',x.filled],['reserved',x.reserved],['curing',x.inOven],['uncovered',x.uncovered]].map(([cl,n])=>`<span class="${cl}" style="width:${n/o.total*100}%" title="${cl}: ${n} sheets"></span>`).join('')}</div>
   <div class="build-stages"><div><i class="released"></i><span>Released downstream</span><strong>${f(x.filled)}</strong></div><div><i class="reserved"></i><span>Reserved in supermarket</span><strong>${f(x.reserved)}</strong></div><div><i class="curing"></i><span>In oven</span><strong>${f(x.inOven)}</strong></div><div><i class="uncovered"></i><span>Still uncovered</span><strong>${f(x.uncovered)}</strong></div></div>
   ${!o.inPlan?'<p class="critical-note">Outside the plan dates. Extend the schedule to see this build.</p>':!x.active?'<p class="critical-note">Reservations begin within 28 days of the Akro-needed date.</p>':x.lateOven?`<p class="critical-note red-text">${f(x.lateOven)} assigned oven sheets finish after the Akro-needed date.</p>`:x.nextOvenOut?`<p class="critical-note">Next assigned oven output: ${d(x.nextOvenOut)}</p>`:'<p class="critical-note">Readiness counts cured sheets only; oven sheets are still in process.</p>'}
   <div class="critical-milestones"><div><span>Akro needed</span><strong>${d(dateStr(o.needBy))}</strong></div><div><span>Fully cured coverage</span><strong>${stockDate}</strong></div><div><span>Final Akro release</span><strong>${d(o.ready)}</strong></div><div><span>Ready-to-ship target</span><strong>${d(o.target)}</strong>${o.accepted?`<small>Original ${d(o.due)}</small>`:''}</div></div>
   <div class="critical-delivery"><div><span>Projected ready to ship</span><strong>${d(o.projected)}</strong></div>${badge(o.tone,o.label)}<button data-editorder="${o.partIndex}" data-week="${o.week}" aria-label="Edit ${esc(o.part)} ${o.week} delivery">Edit dates / lead time</button></div>
   ${buildTimeline(s,o,milestones.get(o.id))}
   ${o.partial?'<p class="critical-note">Partial horizon: start the plan before the full Akro release window to assess this build.</p>':''}
   <div class="critical-trend"><span>Akro-ready sheets across the plan</span>${progressChart(o,rows,date)}<small>Green: released + reserved · Gray: selected date · Gold: Akro needed</small></div>
  </article>`;
 }).join('')}</div>
 <section class="card"><details class="critical-daily"><summary>Daily progress by critical build</summary><div class="critical-table-head"><label>Build<select id="criticalGroup" aria-label="Critical build daily table">${groups.map(o=>`<option value="${esc(o.id)}" ${selected.id===o.id?'selected':''}>${esc(o.part)} · ${o.week}</option>`).join('')}</select></label><p>Cumulative planned position at day end, in whole sheets.</p></div><div class="scroll"><table class="critical-daily-table"><thead><tr><th>Date</th><th>Released</th><th>Reserved</th><th>In oven</th><th>Uncovered</th><th>Akro ready</th></tr></thead><tbody>${rows.map(r=>{const x=r.criticalProgress.find(x=>x.id===selected.id)||zero(selected);return `<tr class="${r.date===date?'selected-progress-day':''}"><td><strong>${d(r.date)}</strong>${r.holiday?'<small>Holiday</small>':r.closed?'<small>Waterjet shutdown</small>':''}</td><td>${f(x.filled)}</td><td>${f(x.reserved)}</td><td>${f(x.inOven)}</td><td>${f(x.uncovered)}</td><td>${f(x.ready)} / ${f(selected.total)} · ${f(x.percent)}%</td></tr>`}).join('')}</tbody></table></div></details></section>
 <p class="table-footnote">Each sheet is assigned to only one critical group at a time. Ready sheets include cumulative releases and stock still reserved in the supermarket. In-oven quantities are sheet allocations; a physical cart may support more than one group. These are Akro forecasts, not counts of finished cases. An order is ready to ship when its last batch clears QC. If step times are incomplete, readiness uses the entered calendar-day allowance.</p>`}`;
}
